        category = _numeric_snapshot(
            "Detailed sleep",
            "Latest night",
            payload,
            {
                "sleepScores.overall.value": ("Sleep score", "score"),
                "deepSleepSeconds": ("Deep sleep", "hours"),
            },
        )

        self.assertEqual(category["fields"]["Sleep score"]["value"], 82)
        self.assertEqual(category["fields"]["Deep sleep"]["value"], 1.0)

