    def test_briefing_suggests_easy_or_rest_when_multiple_signals_are_outside_range(self) -> None:
        metrics = {
            "hrv": {"label": "HRV", "status": "below_usual", "usualRange28": [45, 60], "unit": "ms"},
            "sleep": {"label": "Sleep duration", "status": "below_usual", "usualRange28": [6.5, 8.5], "unit": "hours"},
            "restingHeartRate": {"label": "Resting heart rate", "status": "within_usual", "usualRange28": [42, 50], "unit": "bpm"},
            "stress": {"label": "Stress", "status": "within_usual", "usualRange28": [15, 35], "unit": "score"},
        }

        briefing = build_training_briefing(metrics)

        self.assertEqual(briefing["approach"], "Consider rest or an easy session today.")
        self.assertEqual(len(briefing["evidence"]), 2)
        self.assertIn("not medical advice", briefing["medicalDisclaimer"])

