    def test_training_context_summarizes_recent_and_prior_activity_time(self) -> None:
        end_date = date(2026, 10, 23)
        activities = [
            {
                "startTimeLocal": f"{(end_date - timedelta(days=2)).isoformat()}T07:00:00",
                "duration": 3600,
                "distance": 5000,
                "activityTrainingLoad": 42.5,
            },
            {
                "startTimeLocal": f"{(end_date - timedelta(days=10)).isoformat()}T07:00:00",
                "duration": 7200,
                "distance": 10000,
                "activityTrainingLoad": 60.0,
            },
        ]

        context = build_training_context(activities, end_date)

        self.assertTrue(context["available"])
        self.assertEqual(context["last7Days"]["activityCount"], 1)
        self.assertEqual(context["last7Days"]["durationMinutes"], 60)
        self.assertEqual(context["last7Days"]["distanceKm"], 5.0)
        self.assertEqual(context["last7Days"]["activityTrainingLoad"], 42.5)
        self.assertEqual(context["previous28DaysWeeklyAverageMinutes"], 30)
        self.assertEqual(context["previous28DaysWeeklyAverageActivityLoad"], 15.0)

    def test_large_personal_volume_increase_is_cautioned_but_not_called_acute_load(self) -> None:
        metrics = {
            key: {"label": key, "status": "within_usual", "usualRange28": [1, 10], "unit": ""}
            for key in ("hrv", "sleep", "restingHeartRate", "stress")
        }
        training_context = {
            "available": True,
            "last7Days": {"activityCount": 4, "durationMinutes": 360, "distanceKm": None},
            "previous28DaysWeeklyAverageMinutes": 150,
            "volumeStatus": "well_above_recent",
        }

        briefing = build_training_briefing(metrics, training_context)

        self.assertEqual(briefing["approach"], "Consider an easy session or rest today.")
        self.assertEqual(briefing["evidence"][0]["metric"], "Weekly activity duration")
        self.assertIn("much higher than usual", briefing["explanation"])
        self.assertNotIn("acute load", briefing["explanation"])

